-- Story 25.3: the Child Profile (module child). Family-owned and tenant-scoped (AD-2). No real name
-- and no date of birth (FR-2): a required nickname and a free-text age band. Primary keys are
-- UUIDv7 generated by the application. This story adds no write endpoint.

CREATE TABLE child_profile (
    id               uuid PRIMARY KEY,
    family_id        uuid        NOT NULL UNIQUE REFERENCES families ON DELETE CASCADE,
    nickname         text        NOT NULL CHECK (btrim(nickname) <> ''),
    age_band         text,
    interests        text,
    materials        text,
    engagement_notes text,
    created_at       timestamptz NOT NULL DEFAULT now(),
    UNIQUE (id, family_id)
);

-- One row per sensitivity: its text and whether it is to be avoided.
CREATE TABLE child_sensitivity (
    id               uuid PRIMARY KEY,
    family_id        uuid        NOT NULL REFERENCES families ON DELETE CASCADE,
    child_profile_id uuid        NOT NULL,
    ordinal          integer     NOT NULL,
    text             text        NOT NULL CHECK (btrim(text) <> ''),
    avoid            boolean     NOT NULL DEFAULT false,
    created_at       timestamptz NOT NULL DEFAULT now(),
    -- Composite: a sensitivity cannot name another Family's profile. An owned part, so it goes with it.
    FOREIGN KEY (child_profile_id, family_id) REFERENCES child_profile (id, family_id) ON DELETE CASCADE
);

CREATE INDEX child_sensitivity_profile ON child_sensitivity (family_id, child_profile_id);
